@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if n == "imported":
			n = d.get_next()
			continue
		var p := (base + "/" + n) if base != "" else n
		if d.current_is_dir():
			_walk(p, out)
		else:
			out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk(".godot", files)
	var lines: Array = []
	for f in files:
		var fs := String(f)
		var sz := FileAccess.open("res://" + fs, FileAccess.READ)
		var size := 0
		if sz != null:
			size = sz.get_length()
			sz.close()
		lines.append(fs + " | " + str(size) + "B")
	return "GODOT_CACHE " + str(lines.size()) + " files | " + str(lines.slice(0, 40))
